-- DOMARO V23 — Inventory Center\n-- Adds an atomic stock adjustment RPC for product-authorized admins.\n\ncreate or replace function public.adjust_product_stock(\n  p_product_id text,\n  p_delta integer\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_product public.products%rowtype;\n  v_new_quantity integer;\nbegin\n  if not public.has_admin_permission('products') then\n    raise exception 'Not authorized to manage products' using errcode = '42501';\n  end if;\n\n  if p_product_id is null or btrim(p_product_id) = '' then\n    raise exception 'Product ID is required' using errcode = '22023';\n  end if;\n\n  if p_delta is null or p_delta = 0 then\n    raise exception 'Stock adjustment must be a non-zero whole number' using errcode = '22023';\n  end if;\n\n  select *\n    into v_product\n  from public.products\n  where id = p_product_id\n  for update;\n\n  if not found then\n    raise exception 'Product not found' using errcode = 'P0002';\n  end if;\n\n  if v_product.stock_quantity is null then\n    raise exception 'Stock is not tracked for this product' using errcode = '22023';\n  end if;\n\n  v_new_quantity := v_product.stock_quantity + p_delta;\n\n  if v_new_quantity < 0 then\n    raise exception 'Stock cannot go below zero' using errcode = '22023';\n  end if;\n\n  update public.products\n  set\n    stock_quantity = v_new_quantity,\n    in_stock = (v_new_quantity > 0),\n    updated_at = now()\n  where id = p_product_id\n  returning * into v_product;\n\n  return to_jsonb(v_product);\nend;\n$$;\n\nrevoke all on function public.adjust_product_stock(text, integer) from public;\ngrant execute on function public.adjust_product_stock(text, integer) to authenticated;\n